CREATE TABLE IF NOT EXISTS period_close_readiness_packets (id INTEGER PRIMARY KEY, packet_hash TEXT NOT NULL UNIQUE CHECK(length(packet_hash)=64), period_start TEXT NOT NULL, period_end TEXT NOT NULL, cutoff TEXT NOT NULL, packet_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS period_close_decisions (id INTEGER PRIMARY KEY, period_id INTEGER NOT NULL REFERENCES accounting_periods(id), packet_hash TEXT NOT NULL REFERENCES period_close_readiness_packets(packet_hash), decision TEXT NOT NULL CHECK(decision IN ('closed','forced_closed','reopened')), actor TEXT NOT NULL, reason TEXT, supersedes_decision_id INTEGER REFERENCES period_close_decisions(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS period_close_open_items (id INTEGER PRIMARY KEY, decision_id INTEGER NOT NULL REFERENCES period_close_decisions(id), period_id INTEGER NOT NULL REFERENCES accounting_periods(id), packet_hash TEXT NOT NULL REFERENCES period_close_readiness_packets(packet_hash), code TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('blocker','warning')), count INTEGER NOT NULL, amount NUMERIC NOT NULL, evidence_json TEXT NOT NULL, reason TEXT NOT NULL, actor TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status='open'), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_period_close_decisions_period ON period_close_decisions(period_id,id);
CREATE INDEX IF NOT EXISTS idx_period_close_open_items_period ON period_close_open_items(period_id,id);
CREATE TRIGGER period_close_readiness_packets_no_update BEFORE UPDATE ON period_close_readiness_packets BEGIN SELECT RAISE(ABORT, 'close readiness packets are immutable'); END;
CREATE TRIGGER period_close_readiness_packets_no_delete BEFORE DELETE ON period_close_readiness_packets BEGIN SELECT RAISE(ABORT, 'close readiness packets are append-only'); END;
CREATE TRIGGER period_close_decisions_no_update BEFORE UPDATE ON period_close_decisions BEGIN SELECT RAISE(ABORT, 'period close decisions are immutable'); END;
CREATE TRIGGER period_close_decisions_no_delete BEFORE DELETE ON period_close_decisions BEGIN SELECT RAISE(ABORT, 'period close decisions are append-only'); END;
CREATE TRIGGER period_close_open_items_no_update BEFORE UPDATE ON period_close_open_items BEGIN SELECT RAISE(ABORT, 'period close open items are append-only'); END;
CREATE TRIGGER period_close_open_items_no_delete BEFORE DELETE ON period_close_open_items BEGIN SELECT RAISE(ABORT, 'period close open items are append-only'); END;
